srcDoc.css:
body {
  margin: 0;
  font-family: Inter, Arial, sans-serif;
  color: #101828;
  background: transparent;
}

.invoice-overview {
  width: 100%;
  min-height: 100%;
  box-sizing: border-box;
  padding: 14px;
}

.hero {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: stretch;
  padding: 18px;
  border: 1px solid #d0d5dd;
  background: #ffffff;
}

.eyebrow {
  display: block;
  color: #2563eb;
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
  margin-bottom: 6px;
}

.hero h1 {
  margin: 0;
  font-size: 28px;
  line-height: 1.1;
  letter-spacing: 0;
}

.hero p {
  margin: 8px 0 0;
  color: #667085;
  font-size: 13px;
}

.hero-actions {
  display: grid;
  gap: 10px;
  min-width: 280px;
}

.print-overview {
  height: 38px;
  border: 0;
  background: #101828;
  color: white;
  font-weight: 800;
  cursor: pointer;
}

.hero-total {
  padding: 14px;
  background: #101828;
  color: white;
}

.hero-total span,
.hero-total small {
  display: block;
  color: #d0d5dd;
  font-size: 12px;
}

.hero-total strong {
  display: block;
  margin: 8px 0 6px;
  font-size: 26px;
  line-height: 1.1;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-top: 12px;
}

.stat-card {
  display: flex;
  gap: 12px;
  padding: 14px;
  border: 1px solid #d0d5dd;
  background: #ffffff;
}

.stat-icon {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #101828;
  color: white;
  font-weight: 900;
}

.stat-card span,
.stat-card small {
  display: block;
  color: #667085;
  font-size: 11px;
}

.stat-card strong {
  display: block;
  margin: 4px 0;
  font-size: 19px;
  line-height: 1.15;
}

.stat-card.blue .stat-icon {
  background: #2563eb;
}

.stat-card.green .stat-icon {
  background: #047857;
}

.stat-card.amber .stat-icon {
  background: #b45309;
}

.stat-card.dark .stat-icon {
  background: #101828;
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 12px;
  margin-top: 12px;
}

.chart-panel,
.side-panel {
  border: 1px solid #d0d5dd;
  background: #ffffff;
  padding: 14px;
}

.panel-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 12px;
}

.panel-head h2 {
  margin: 0;
  font-size: 16px;
}

.panel-head span {
  display: block;
  margin-top: 3px;
  color: #667085;
  font-size: 12px;
}

.bar-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(56px, 1fr));
  gap: 8px;
  align-items: end;
}

.bar-item {
  min-width: 0;
  text-align: center;
}

.bar-track {
  height: 112px;
  display: flex;
  align-items: end;
  justify-content: center;
  background: #f2f4f7;
  border: 1px solid #eaecf0;
}

.bar {
  width: 58%;
  background: #2563eb;
}

.bar.negative {
  background: #dc2626;
}

.bar-item span {
  display: block;
  margin-top: 6px;
  color: #667085;
  font-size: 10px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.bar-item b {
  display: block;
  margin-top: 2px;
  font-size: 11px;
}

.status-list {
  display: grid;
  gap: 8px;
}

.status-list div {
  display: flex;
  justify-content: space-between;
  padding: 10px;
  background: #f8fafc;
  border: 1px solid #eaecf0;
}

.status-list span {
  color: #667085;
  font-size: 12px;
}

.status-list b {
  font-size: 13px;
}

.mini-summary {
  margin-top: 12px;
  padding: 14px;
  background: #101828;
  color: white;
}

.mini-summary span,
.mini-summary small {
  display: block;
  color: #d0d5dd;
  font-size: 12px;
}

.mini-summary strong {
  display: block;
  margin: 5px 0;
  font-size: 18px;
}

@media (max-width: 900px) {
  .hero,
  .content-grid {
    display: grid;
    grid-template-columns: 1fr;
  }
  .stats-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .hero-actions {
    min-width: 0;
  }
}
@page {
  size: A4 landscape;
  margin: 10mm;
}
@media print {
  body {
    background: white;
  }
  .no-print {
    display: none !important;
  }
  .invoice-overview {
    padding: 0;
  }
  .hero,
  .stat-card,
  .chart-panel,
  .side-panel {
    break-inside: avoid;
    box-shadow: none;
  }
  .hero {
    margin-bottom: 10px;
  }
  .stats-grid,
  .content-grid {
    break-inside: avoid;
  }
}

