  const max = Math.max(1, ...rows.map(row => Math.abs(rowTotal(row))));
  const last = rows[rows.length - 1] || {};
  const best = [...rows].sort((a, b) => rowTotal(b) - rowTotal(a))[0] || {};

  const printOverview = () => {
    window.print();
  };

  return (
    <div className="invoice-overview">
      <div className="hero">
        <div>
          <span className="eyebrow">Invoice analytics</span>
          <h1>{periodLabel(period)} invoice overview</h1>
          <p>{rows.length} period{rows.length === 1 ? "" : "s"} loaded</p>
        </div>

        <div className="hero-actions">
          <button className="print-overview no-print" onClick={printOverview}>
            Print
          </button>

          <div className="hero-total">
            <span>Total revenue</span>
            <strong>{money(totals.totalAmount, currency)}</strong>
            <small>Open amount: {money(totals.openAmount, currency)}</small>
          </div>
        </div>
      </div>

      <div className="stats-grid">
        <StatCard
          label="Documents"
          value={num(totals.documentCount)}
          hint={`${num(totals.invoiceCount)} invoices / ${num(totals.creditNoteCount)} credit notes`}
          tone="blue"
        />
        <StatCard
          label="Paid"
          value={money(totals.paidAmount, currency)}
          hint={`Tax: ${money(totals.taxAmount, currency)}`}
          tone="green"
        />
        <StatCard
          label="Open"
          value={money(totals.openAmount, currency)}
          hint={`${num(totals.draftCount)} drafts / ${num(totals.postedCount)} posted`}
          tone="amber"
        />
        <StatCard
          label="Average"
          value={money(averageInvoice, currency)}
          hint={`Best: ${rowLabel(best)} ${best.totalAmount ? money(rowTotal(best), currency) : ""}`}
          tone="dark"
        />
      </div>

      <div className="content-grid">
        <div className="chart-panel">
          <div className="panel-head">
            <div>
              <h2>Revenue trend</h2>
              <span>{periodLabel(period)} totals from selected filters</span>
            </div>
          </div>

          <div className="bar-grid">
            {rows.map((row, index) => {
              const amount = rowTotal(row);
              const height = Math.max(8, (Math.abs(amount) / max) * 92);

              return (
                <div className="bar-item" key={index}>
                  <div className="bar-track">
                    <div
                      className={amount < 0 ? "bar negative" : "bar"}
                      style={{ height: `${height}%` }}
                    />
                  </div>
                  <span title={rowLabel(row)}>{rowLabel(row)}</span>
                  <b>{shortMoney(amount)}</b>
                </div>
              );
            })}
          </div>
        </div>

        <div className="side-panel">
          <div className="panel-head">
            <div>
              <h2>Status mix</h2>
              <span>Current filtered documents</span>
            </div>
          </div>

          <div className="status-list">
            <div><span>Posted</span><b>{num(totals.postedCount)}</b></div>
            <div><span>Draft</span><b>{num(totals.draftCount)}</b></div>
            <div><span>Cancelled</span><b>{num(totals.cancelledCount)}</b></div>
            <div><span>Credit notes</span><b>{num(totals.creditNoteCount)}</b></div>
          </div>

          <div className="mini-summary">
            <span>Latest period</span>
            <strong>{rowLabel(last)}</strong>
            <small>{money(rowTotal(last), currency)}</small>
          </div>
        </div>
      </div>
    </div>
  );
}

function render(model = window.appsmith?.model || {}) {
  ReactDOM.render(<App model={model || {}} />, document.getElementById("root"));
}

window.appsmith.onReady(() => {
  render(window.appsmith.model);

  window.appsmith.onModelChange((model) => {
    render(model);
  });
});
